#!/usr/bin/env node
/**
 * Renders the static business site from project.template.json (defaults)
 * merged with project.config.json params (when generated by OMNIFORGE).
 * Output: dist/ — a fully standalone site. No network, no dependencies.
 */
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = fileURLToPath(new URL("..", import.meta.url));

function readJson(p) {
  return existsSync(p) ? JSON.parse(readFileSync(p, "utf8")) : null;
}

const defaults = readJson(join(ROOT, "project.template.json")) ?? {};
const generated = readJson(join(ROOT, "project.config.json"));
const params = (generated && generated.params) || {};
const cfg = {
  ...defaults,
  ...params,
  business: { ...(defaults.business ?? {}), ...(params.business ?? {}) },
  contact: { ...(defaults.contact ?? {}), ...(params.contact ?? {}) },
  theme: { ...(defaults.theme ?? {}), ...(params.theme ?? {}) },
  seo: { ...(defaults.seo ?? {}), ...(params.seo ?? {}) },
  services: Array.isArray(params.services) && params.services.length > 0 ? params.services : defaults.services ?? [],
};

const business = cfg.business ?? {};
const contact = cfg.contact ?? {};
const theme = cfg.theme ?? {};
const seo = cfg.seo ?? {};

const escapeHtml = (s) =>
  String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

const servicesHtml = (cfg.services ?? [])
  .map(
    (s) =>
      `<article class="card"><h3>${escapeHtml(s.name)}</h3><p>${escapeHtml(s.description)}</p></article>`
  )
  .join("\n        ");

const whatsappDigits = String(contact.whatsapp ?? "").replace(/[^0-9]/g, "");
const whatsappLink = whatsappDigits
  ? `<a class="btn btn-accent" href="https://wa.me/${whatsappDigits}" rel="noopener">Chat on WhatsApp</a>`
  : "";

const tokens = {
  LOCALE: cfg.locale || "en",
  PAGE_TITLE: escapeHtml(seo.title || `${business.name} — Home`),
  SEO_DESCRIPTION: escapeHtml(seo.description || business.description || ""),
  BUSINESS_NAME: escapeHtml(business.name ?? "Sample Business"),
  TAGLINE: escapeHtml(business.tagline ?? ""),
  DESCRIPTION: escapeHtml(business.description ?? ""),
  SERVICES_HTML: servicesHtml,
  HOURS: escapeHtml(contact.hours ?? ""),
  PHONE: escapeHtml(contact.phone ?? ""),
  PHONE_RAW: String(contact.phone ?? "").replace(/[^0-9+]/g, ""),
  EMAIL: escapeHtml(contact.email ?? ""),
  ADDRESS: escapeHtml(contact.address ?? ""),
  WHATSAPP_LINK: whatsappLink,
  YEAR: String(new Date().getFullYear()),
  PRIMARY: theme.primary ?? "#0f766e",
  ACCENT: theme.accent ?? "#f59e0b",
  BG: theme.bg ?? "#fafaf9",
  TEXT: theme.text ?? "#1c1917",
  PRIMARY_HEX: String(theme.primary ?? "#0f766e").replace("#", ""),
};

mkdirSync(join(ROOT, "dist"), { recursive: true });
for (const file of ["index.html", "styles.css", "main.js"]) {
  const src = readFileSync(join(ROOT, "src", file), "utf8");
  const out = src.replace(/\{\{([A-Z_]+)\}\}/g, (_, key) => tokens[key] ?? "");
  const dest = join(ROOT, "dist", file);
  mkdirSync(dirname(dest), { recursive: true });
  writeFileSync(dest, out, "utf8");
}
// copy notices + a README into the deliverable
for (const f of ["THIRD-PARTY-NOTICES.md"]) {
  if (existsSync(join(ROOT, f))) writeFileSync(join(ROOT, "dist", f), readFileSync(join(ROOT, f), "utf8"), "utf8");
}
console.log("rendered dist/ — open dist/index.html or run: npx serve dist");
